-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 21 recettes, 15 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, ph->>'page',
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"cullen-skink","country":"GB","original":"Cullen skink","title":"Cullen skink écossais (soupe de haddock fumé et pommes de terre)","en":"Scottish Cullen skink (smoked haddock chowder)","es":"Cullen skink escocés (sopa de eglefino ahumado)","desc":"Soupe épaisse de haddock fumé, pommes de terre, oignon et lait, originaire du village de pêcheurs de Cullen sur la côte du Moray.","cat":"Soupe","diff":"easy","prep":15,"cook":30,"serv":4,"place":{"slug":"gb-cullen","name":"Cullen","type":"locality","lat":57.692,"lng":-2.82,"summary":"Village de pêcheurs du Moray (Écosse) qui a donné son nom au Cullen skink."},"ing":[["Haddock fumé (Finnan haddie)",450,"g",null],["Lait entier",600,"ml",null],["Pommes de terre farineuses",400,"g","en dés"],["Oignon",1,null,"haché"],["Beurre",30,"g",null],["Feuille de laurier",1,null,null],["Ciboulette ou persil",2,"c. à soupe",null],["Poivre",0.5,"c. à thé",null]],"steps":["Pocher le haddock 5 minutes dans le lait avec le laurier; le retirer et l’effeuiller.","Faire fondre l’oignon au beurre.","Ajouter les pommes de terre, 300 ml d’eau et cuire 15 minutes.","Écraser grossièrement une partie des pommes de terre.","Ajouter le lait de pochage et le poisson; réchauffer sans bouillir.","Poivrer, parsemer de ciboulette et servir avec du pain."],"photo":{"file":"File:Cullen skink - January 2014.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/8/83/Cullen_skink_-_January_2014.jpg","page":"https://commons.wikimedia.org/wiki/File:Cullen_skink_-_January_2014.jpg","author":"Pseph","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"cranachan","country":"GB","original":"Cranachan","title":"Cranachan écossais (crème, framboises, avoine grillée et whisky)","en":"Scottish cranachan","es":"Cranachan escocés","desc":"Dessert des moissons écossaises : crème fouettée au miel de bruyère et au whisky, framboises fraîches et flocons d’avoine grillés.","cat":"Dessert","diff":"easy","prep":15,"cook":5,"serv":4,"place":"gb-scotland","ing":[["Flocons d’avoine",60,"g",null],["Crème 35 %",300,"ml",null],["Miel de bruyère",3,"c. à soupe",null],["Whisky écossais",2,"c. à soupe",null],["Framboises",300,"g",null]],"steps":["Griller les flocons d’avoine à sec jusqu’à ce qu’ils sentent la noisette; laisser refroidir.","Fouetter la crème en pics souples.","Incorporer le miel et le whisky.","Écraser légèrement un tiers des framboises.","Alterner dans des verres crème, framboises et avoine grillée.","Finir par des framboises entières, un filet de miel et de l’avoine."],"photo":{"file":"File:Cranachan (4332953688).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/Cranachan_%284332953688%29.jpg/1280px-Cranachan_%284332953688%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Cranachan_(4332953688).jpg","author":"Saskia van de Nieuwenhof from Edinburgh, United Kingdom","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"welsh-cawl","country":"GB","original":"Cawl","title":"Cawl gallois (soupe d’agneau, poireaux et légumes racines)","en":"Welsh cawl (lamb and leek broth)","es":"Cawl galés (sopa de cordero y puerros)","desc":"Plat national du pays de Galles : agneau mijoté avec poireaux, pommes de terre, carottes et rutabaga, servi avec du pain et du fromage de Caerphilly.","cat":"Soupe","diff":"easy","prep":20,"cook":150,"serv":6,"place":{"slug":"gb-wales","name":"Pays de Galles","type":"region","lat":52.3,"lng":-3.7,"summary":"Nation du Royaume-Uni : cawl, Welsh rarebit, bara brith et Welsh cakes."},"ing":[["Collier ou épaule d’agneau",1,"kg","en morceaux"],["Poireaux",3,null,"émincés"],["Pommes de terre",600,"g","en morceaux"],["Carottes",3,null,"en rondelles"],["Rutabaga",300,"g","en dés"],["Oignon",1,null,"haché"],["Persil",1,"poignée",null],["Sel et poivre",1.5,"c. à thé",null]],"steps":["Couvrir l’agneau d’eau froide, porter à ébullition et écumer.","Mijoter 1 heure.","Ajouter oignon, carottes et rutabaga; cuire 30 minutes.","Ajouter les pommes de terre et la moitié des poireaux; cuire 30 minutes.","Ajouter le reste des poireaux 5 minutes avant la fin.","Assaisonner, parsemer de persil; c’est encore meilleur le lendemain."],"photo":{"file":"File:Cawl in bowl.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Cawl_in_bowl.jpg/1280px-Cawl_in_bowl.jpg","page":"https://commons.wikimedia.org/wiki/File:Cawl_in_bowl.jpg","author":"Serenpop","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"welsh-rarebit","country":"GB","original":"Welsh rarebit","title":"Welsh rarebit (toast gratiné à la sauce cheddar et bière)","en":"Welsh rarebit","es":"Welsh rarebit (tostada con salsa de queso y cerveza)","desc":"Pain grillé nappé d’une sauce épaisse de cheddar fondu à la bière, moutarde et sauce Worcestershire, passée sous le gril.","cat":"Entrée","diff":"easy","prep":10,"cook":10,"serv":4,"place":{"slug":"gb-wales","name":"Pays de Galles","type":"region","lat":52.3,"lng":-3.7,"summary":"Nation du Royaume-Uni : cawl, Welsh rarebit, bara brith et Welsh cakes."},"ing":[["Cheddar affiné",250,"g","râpé"],["Bière brune",80,"ml",null],["Beurre",25,"g",null],["Farine",1,"c. à soupe",null],["Moutarde anglaise",1,"c. à thé",null],["Sauce Worcestershire",1,"c. à soupe",null],["Jaune d’œuf",1,null,null],["Pain de campagne",4,"tranches épaisses",null]],"steps":["Faire fondre le beurre, ajouter la farine et cuire 1 minute.","Verser la bière en fouettant.","Ajouter fromage, moutarde et Worcestershire jusqu’à sauce lisse.","Hors du feu, incorporer le jaune d’œuf.","Griller le pain et le napper généreusement de sauce.","Passer sous le gril jusqu’à ce que ce soit doré et bouillonnant."],"photo":{"file":"File:Hix Oyster and Chop House, Smithfield, London (4337485356).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/Hix_Oyster_and_Chop_House%2C_Smithfield%2C_London_%284337485356%29.jpg/1280px-Hix_Oyster_and_Chop_House%2C_Smithfield%2C_London_%284337485356%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Hix_Oyster_and_Chop_House,_Smithfield,_London_(4337485356).jpg","author":"Ewan Munro from London, UK","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"bara-brith","country":"GB","original":"Bara brith","title":"Bara brith gallois (pain aux fruits secs trempés dans le thé)","en":"Welsh bara brith (tea loaf)","es":"Bara brith galés (pan de frutas al té)","desc":"« Pain moucheté » gallois : fruits secs trempés une nuit dans du thé noir, mélangés à la farine, aux épices et à la cassonade, servi en tranches beurrées.","cat":"Dessert","diff":"easy","prep":15,"cook":75,"serv":10,"place":{"slug":"gb-wales","name":"Pays de Galles","type":"region","lat":52.3,"lng":-3.7,"summary":"Nation du Royaume-Uni : cawl, Welsh rarebit, bara brith et Welsh cakes."},"ing":[["Fruits secs mélangés",400,"g",null],["Thé noir chaud",300,"ml",null],["Cassonade",150,"g",null],["Farine à levure (self-raising)",300,"g",null],["Œuf",1,null,"battu"],["Épices mélangées (mixed spice)",1,"c. à thé",null],["Beurre",1,"portion","pour servir"]],"steps":["Faire tremper fruits et cassonade dans le thé une nuit.","Préchauffer le four à 160 °C et chemiser un moule à cake.","Incorporer farine, épices et œuf au mélange.","Verser dans le moule.","Cuire 1 h 15 jusqu’à ce qu’une lame ressorte sèche.","Laisser refroidir et servir tranché et beurré."],"photo":{"file":"File:Bara Brith (3320696816).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Bara_Brith_%283320696816%29.jpg/1280px-Bara_Brith_%283320696816%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Bara_Brith_(3320696816).jpg","author":"zingyyellow...! from Wales Cymru UK","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"yorkshire-pudding","country":"GB","original":"Yorkshire pudding","title":"Yorkshire pudding (soufflés de pâte au jus de rôti)","en":"Yorkshire pudding","es":"Yorkshire pudding (buñuelos horneados)","desc":"Pâte à crêpes épaisse cuite dans la graisse brûlante du rôti jusqu’à gonfler en coupelles croustillantes, servie avec le rosbif et la gravy du dimanche.","cat":"Accompagnement","diff":"easy","prep":10,"cook":25,"serv":6,"place":{"slug":"gb-yorkshire","name":"Yorkshire","type":"region","lat":54,"lng":-1.5,"summary":"Comté du nord de l’Angleterre : Yorkshire pudding, parkin et Wensleydale."},"ing":[["Farine",140,"g",null],["Œufs",4,null,null],["Lait",200,"ml",null],["Sel",0.5,"c. à thé",null],["Graisse de bœuf ou huile",6,"c. à soupe",null]],"steps":["Fouetter farine, œufs, lait et sel en pâte lisse; reposer 30 minutes.","Préchauffer le four à 230 °C.","Mettre une cuillère de graisse dans chaque alvéole d’un moule à muffins et chauffer 10 minutes.","Verser la pâte rapidement dans la graisse fumante.","Cuire 20 à 25 minutes sans ouvrir le four.","Servir aussitôt avec la gravy."],"photo":{"file":"File:Yorkshire-puddings.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Yorkshire-puddings.jpg/1280px-Yorkshire-puddings.jpg","page":"https://commons.wikimedia.org/wiki/File:Yorkshire-puddings.jpg","author":"Richard W.M. Jones (talk)","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"bakewell-tart","country":"GB","original":"Bakewell tart","title":"Bakewell tart (tarte à la frangipane et confiture de framboises)","en":"Bakewell tart","es":"Tarta Bakewell (frangipana y mermelada de frambuesa)","desc":"Pâte sablée garnie de confiture de framboises et d’une frangipane aux amandes, glacée et décorée d’une cerise, originaire de la petite ville de Bakewell dans le Derbyshire.","cat":"Dessert","diff":"medium","prep":30,"cook":40,"serv":8,"place":{"slug":"gb-bakewell","name":"Bakewell","type":"locality","lat":53.2141,"lng":-1.6763,"summary":"Bourg du Peak District (Derbyshire), patrie du Bakewell pudding et de la Bakewell tart."},"ing":[["Pâte sablée",300,"g",null],["Confiture de framboises",4,"c. à soupe",null],["Beurre mou",125,"g",null],["Sucre",125,"g",null],["Œufs",2,null,null],["Poudre d’amande",125,"g",null],["Farine",25,"g",null],["Extrait d’amande",0.5,"c. à thé",null],["Sucre glace",150,"g","pour le glaçage"],["Cerises confites",8,null,null]],"steps":["Foncer un moule de 23 cm et précuire 15 minutes à 180 °C.","Étaler la confiture sur le fond.","Crémer beurre et sucre, ajouter œufs, amande, farine et extrait.","Étaler la frangipane sur la confiture.","Cuire 25 minutes à 170 °C; refroidir.","Glacer au sucre glace délayé d’eau et décorer de cerises."],"photo":{"file":"File:Bakewell tart on a plate.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/Bakewell_tart_on_a_plate.jpg/1280px-Bakewell_tart_on_a_plate.jpg","page":"https://commons.wikimedia.org/wiki/File:Bakewell_tart_on_a_plate.jpg","author":"Brynn","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"lancashire-hotpot","country":"GB","original":"Lancashire hotpot","title":"Lancashire hotpot (agneau et oignons sous couvercle de pommes de terre)","en":"Lancashire hotpot","es":"Lancashire hotpot (cordero con patatas al horno)","desc":"Agneau et oignons cuits lentement en cocotte sous un toit de rondelles de pommes de terre qui dorent, plat des ouvriers des filatures du Lancashire.","cat":"Ragoût","diff":"easy","prep":25,"cook":150,"serv":6,"place":{"slug":"gb-lancashire","name":"Lancashire","type":"region","lat":53.8,"lng":-2.6,"summary":"Comté du nord-ouest de l’Angleterre : hotpot, Eccles cakes et fromage Lancashire."},"ing":[["Collier ou épaule d’agneau",1,"kg","en morceaux"],["Oignons",3,null,"émincés"],["Pommes de terre",1,"kg","en fines rondelles"],["Beurre",50,"g",null],["Farine",2,"c. à soupe",null],["Bouillon d’agneau",500,"ml",null],["Sauce Worcestershire",1,"c. à soupe",null],["Thym",3,"brins",null],["Sel et poivre",1.5,"c. à thé",null]],"steps":["Fariner et dorer l’agneau au beurre; réserver.","Faire fondre les oignons.","Disposer agneau et oignons dans une cocotte, ajouter thym, Worcestershire et bouillon.","Couvrir de rondelles de pommes de terre qui se chevauchent; badigeonner de beurre.","Cuire 2 heures à 160 °C à couvert.","Découvrir et cuire 30 minutes à 200 °C pour dorer les pommes de terre."],"photo":{"file":"File:Lancashire Hotpot square.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/4/40/Lancashire_Hotpot_square.jpg","page":"https://commons.wikimedia.org/wiki/File:Lancashire_Hotpot_square.jpg","author":"Mike Fleming","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"eccles-cakes","country":"GB","original":"Eccles cakes","title":"Eccles cakes (chaussons feuilletés aux raisins de Corinthe)","en":"Eccles cakes","es":"Eccles cakes (pastelitos de hojaldre con pasas)","desc":"Petits ronds de pâte feuilletée fourrés de raisins de Corinthe au beurre, sucre et épices, incisés de trois fentes et sucrés, de la ville d’Eccles près de Manchester.","cat":"Dessert","diff":"easy","prep":25,"cook":20,"serv":12,"place":{"slug":"gb-lancashire","name":"Lancashire","type":"region","lat":53.8,"lng":-2.6,"summary":"Comté du nord-ouest de l’Angleterre : hotpot, Eccles cakes et fromage Lancashire."},"ing":[["Pâte feuilletée",500,"g",null],["Raisins de Corinthe",200,"g",null],["Beurre fondu",50,"g",null],["Cassonade",75,"g",null],["Écorces confites",30,"g",null],["Muscade et cannelle",0.5,"c. à thé",null],["Blanc d’œuf",1,null,null],["Sucre semoule",2,"c. à soupe",null]],"steps":["Mélanger raisins, beurre, cassonade, écorces et épices.","Abaisser la pâte et découper 12 disques de 10 cm.","Déposer une cuillère de garniture au centre.","Refermer en aumônière, retourner et aplatir légèrement.","Inciser 3 fentes, badigeonner de blanc d’œuf et saupoudrer de sucre.","Cuire 20 minutes à 210 °C."],"photo":{"file":"File:Eccles cakes.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Eccles_cakes.jpg/1280px-Eccles_cakes.jpg","page":"https://commons.wikimedia.org/wiki/File:Eccles_cakes.jpg","author":"Dr Greg","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"ulster-fry","country":"GB","original":"Ulster fry","title":"Ulster fry (petit-déjeuner d’Irlande du Nord, soda farls et potato bread)","en":"Ulster fry","es":"Ulster fry (desayuno de Irlanda del Norte)","desc":"Petit-déjeuner complet d’Irlande du Nord : bacon, saucisses, œufs, boudin, tomate et surtout soda farls et potato bread dorés à la poêle.","cat":"Petit-déjeuner","diff":"easy","prep":10,"cook":25,"serv":2,"place":{"slug":"gb-northern-ireland","name":"Irlande du Nord","type":"region","lat":54.6,"lng":-6.7,"summary":"Province britannique (Belfast) : Ulster fry, soda farls, champ et Comber potatoes."},"ing":[["Bacon de dos",4,"tranches",null],["Saucisses de porc",4,null,null],["Œufs",2,null,null],["Boudin noir",2,"tranches",null],["Tomate",1,null,"coupée en deux"],["Soda farls",2,null,"coupés en deux"],["Potato bread (fadge)",2,null,null],["Beurre ou saindoux",30,"g",null]],"steps":["Cuire les saucisses à feu moyen 12 minutes.","Ajouter bacon et boudin et les dorer.","Griller les demi-tomates dans la même poêle.","Faire dorer soda farls et potato bread dans le gras de cuisson.","Cuire les œufs au plat.","Dresser le tout sur une grande assiette chaude."],"photo":{"file":"File:Full Ulster fry.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/3/37/Full_Ulster_fry.jpg","page":"https://commons.wikimedia.org/wiki/File:Full_Ulster_fry.jpg","author":"Jamezcd at English Wikipedia","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"semla-stockholm","country":"SE","original":"Semla","title":"Semla suédoise (brioche à la cardamome, pâte d’amande et crème)","en":"Swedish semla (cardamom cream bun)","es":"Semla sueca (bollo de cardamomo con crema)","desc":"Brioche à la cardamome dont on retire le chapeau pour la garnir de pâte d’amande et de crème fouettée, mangée pour Mardi gras (fettisdagen).","cat":"Dessert","diff":"medium","prep":40,"cook":15,"serv":12,"place":"se-stockholm","ing":[["Farine",500,"g",null],["Lait tiède",250,"ml",null],["Levure sèche",7,"g",null],["Sucre",80,"g",null],["Beurre mou",100,"g",null],["Cardamome moulue",2,"c. à thé",null],["Œuf",1,null,null],["Pâte d’amande",250,"g",null],["Crème 35 %",400,"ml",null],["Sucre glace",2,"c. à soupe",null]],"steps":["Pétrir farine, lait, levure, sucre, beurre, cardamome et œuf; lever 1 heure.","Façonner 12 boules et lever 40 minutes.","Dorer à l’œuf et cuire 10 à 12 minutes à 220 °C; refroidir.","Couper un chapeau et creuser l’intérieur; mélanger la mie avec la pâte d’amande et un peu de lait.","Garnir de ce mélange puis d’une rosace de crème fouettée.","Remettre le chapeau et saupoudrer de sucre glace."],"photo":{"file":"File:SemlaFlickr.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/SemlaFlickr.jpg/1280px-SemlaFlickr.jpg","page":"https://commons.wikimedia.org/wiki/File:SemlaFlickr.jpg","author":"Frugan","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"raekmacka","country":"SE","original":"Räkmacka","title":"Räkmacka suédoise (tartine aux crevettes nordiques et œuf)","en":"Swedish räkmacka (shrimp open sandwich)","es":"Räkmacka sueca (tostada de gambas)","desc":"Tartine de pain beurré garnie de laitue, œuf dur, montagne de crevettes nordiques, mayonnaise, aneth et citron, classique des côtes de Göteborg.","cat":"Entrée","diff":"easy","prep":15,"cook":10,"serv":2,"place":{"slug":"se-goteborg","name":"Göteborg","type":"city","lat":57.7089,"lng":11.9746,"summary":"Grand port de la côte ouest suédoise, réputé pour ses crevettes et sa Feskekôrka."},"ing":[["Pain de mie ou pain de seigle",2,"tranches",null],["Beurre",20,"g",null],["Laitue",4,"feuilles",null],["Œufs durs",2,null,"en rondelles"],["Crevettes nordiques décortiquées",250,"g",null],["Mayonnaise",3,"c. à soupe",null],["Aneth",1,"poignée",null],["Citron",1,null,"en quartiers"],["Œufs de lump ou caviar de lompe",1,"c. à soupe","facultatif"]],"steps":["Beurrer le pain.","Poser la laitue puis les rondelles d’œuf.","Déposer une généreuse montagne de crevettes.","Ajouter une cuillère de mayonnaise.","Décorer d’aneth, d’œufs de lump et d’un quartier de citron.","Servir aussitôt."],"photo":{"file":"File:Räkmacka.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/5e/R%C3%A4kmacka.jpg","page":"https://commons.wikimedia.org/wiki/File:R%C3%A4kmacka.jpg","author":"Jonas Nordström","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"pinnekjott","country":"NO","original":"Pinnekjøtt","title":"Pinnekjøtt de l’ouest norvégien (côtes d’agneau séchées cuites à la vapeur)","en":"Norwegian pinnekjøtt (steamed cured lamb ribs)","es":"Pinnekjøtt noruego (costillas de cordero curadas al vapor)","desc":"Côtes d’agneau salées et séchées, dessalées puis cuites à la vapeur sur des bâtonnets de bouleau, servies à Noël avec purée de rutabaga et pommes de terre.","cat":"Plat principal","diff":"medium","prep":15,"cook":180,"serv":4,"place":{"slug":"no-vestlandet","name":"Vestlandet","type":"region","lat":61,"lng":6.5,"summary":"Ouest de la Norvège (Bergen, Voss) : pinnekjøtt, raspeballer et fiskesuppe."},"ing":[["Côtes d’agneau salées-séchées (pinnekjøtt)",1.5,"kg",null],["Bâtonnets de bouleau ou grille",1,"portion",null],["Rutabaga",1,"kg",null],["Carottes",2,null,null],["Beurre",50,"g",null],["Muscade",1,"pincée",null],["Pommes de terre",1,"kg",null]],"steps":["Faire tremper les côtes 24 heures dans l’eau froide pour le